<script lang="ts">
	import { onMount } from 'svelte';

	const TAG_ID = 'G-XXXXXXXXXX'; // your Google tag ID
	const TYPES = ['ad_storage', 'analytics_storage', 'ad_user_data', 'ad_personalization'];
	type Choice = 'granted' | 'denied';

	let open = $state(false);
	let loaded = false;

	// Google requires the Arguments object itself on the dataLayer, not an array.
	function gtag(..._args: unknown[]) {
		const w = window as unknown as { dataLayer?: unknown[] };
		(w.dataLayer ??= []).push(arguments);
	}
	function allTypes(value: Choice) {
		return Object.fromEntries(TYPES.map((type) => [type, value]));
	}
	function stored(): Choice | null {
		const match = document.cookie.match(/(?:^|; )consent=(granted|denied)/);
		return match ? (match[1] as Choice) : null;
	}
	function store(value: Choice) {
		// `consent` is an essential cookie: list it in the project's essentialCookies.
		document.cookie = `consent=${value}; Max-Age=31536000; Path=/; SameSite=Lax${location.protocol === 'https:' ? '; Secure' : ''}`;
	}
	function loadTag() {
		if (loaded) return;
		loaded = true;
		const script = document.createElement('script');
		script.async = true;
		// No nonce needed: 'strict-dynamic' trusts a script created by our own (nonced or hashed) script.
		script.src = `https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(TAG_ID)}`;
		document.head.appendChild(script);
		gtag('js', new Date());
		gtag('config', TAG_ID);
	}
	function apply(value: Choice) {
		gtag('consent', 'update', allTypes(value));
		if (value === 'granted') loadTag(); // only after Accept: no Google host is contacted before
	}
	function choose(value: Choice) {
		store(value);
		apply(value);
		open = false;
	}

	onMount(() => {
		gtag('consent', 'default', allTypes('denied')); // before any Google tag request
		const prior = stored();
		if (prior) apply(prior);
		else {
			if ((navigator as Navigator & { globalPrivacyControl?: boolean }).globalPrivacyControl === true) apply('denied');
			open = true;
		}
	});
</script>

{#if open}
	<div id="consent-banner" role="dialog" aria-label="Cookie consent">
		<p>We use analytics cookies only if you accept. <a href="/privacy">Privacy notice</a></p>
		<button type="button" class="consent-btn" onclick={() => choose('granted')}>Accept all</button>
		<button type="button" class="consent-btn" onclick={() => choose('denied')}>Reject all</button>
	</div>
{:else}
	<button type="button" id="consent-reopen" class="consent-link" onclick={() => (open = true)}>Cookie settings</button>
{/if}

<style>
	/* Same size, weight and contrast for both choices: no dark pattern (PRV-002). */
	.consent-btn {
