import { error } from '@sveltejs/kit';
import type { PageServerLoad } from './$types';

type Product = { slug: string; name: string };

// Replace with the project's data access. Return null when the row does not exist; let it throw
// when the backend is down (that is an outage, not a missing page).
async function findProduct(slug: string): Promise<Product | null> {
	const rows: Product[] = [{ slug: 'example', name: 'Example product' }];
	return rows.find((row) => row.slug === slug) ?? null;
}

export const load: PageServerLoad = async ({ params }) => {
	// RTE-004: unknown or malformed params answer 404 before any work (and before anything streams).
	if (!/^[a-z0-9][a-z0-9-]{0,79}$/.test(params.slug)) error(404, 'Product not found');

	let product: Product | null;
	try {
		product = await findProduct(params.slug);
	} catch (cause) {
		console.error(cause);
		error(503, 'This page is temporarily unavailable. Please try again shortly.'); // RTE-007: never 404/200
	}
	if (!product) error(404, 'Product not found');
	return { product };
};

