import { fail, redirect } from '@sveltejs/kit';
import type { Actions } from './$types';
import { FORM_WEBHOOK_URL } from '$app/env/private';

// Origin check (SEC-024): SvelteKit rejects cross-origin form POSTs with 403 by default
// (`csrf` in the kit config; keep `trustedOrigins` empty).
// Pages with actions cannot be prerendered, so do not set `prerender = true` here.

const WINDOW_MS = 10 * 60_000;
const MAX_PER_WINDOW = 5;
const hits = new Map<string, number[]>(); // placeholder: in-memory, per process. Use Redis/your edge for several instances.

function limited(key: string): boolean {
	const now = Date.now();
	const recent = (hits.get(key) ?? []).filter((t) => now - t < WINDOW_MS);
	recent.push(now);
	hits.set(key, recent);
	return recent.length > MAX_PER_WINDOW;
}

export const actions = {
	default: async ({ request, getClientAddress }) => {
		let ip = 'unknown';
		try {
			ip = getClientAddress();
		} catch {
			/* adapter cannot tell */
		}
		if (limited(ip)) return fail(429, { error: 'Too many messages. Please try again later.', name: '', email: '', message: '' }); // SEC-054

		const form = await request.formData();
		const name = String(form.get('name') ?? '').trim();
		const email = String(form.get('email') ?? '').trim();
		const message = String(form.get('message') ?? '').trim();

		// SEC-055: honeypot. Bots fill the hidden field; answer like a success and do nothing.
		// (Alternative: Cloudflare Turnstile - read `cf-turnstile-response` and verify it server-side.)
		if (String(form.get('website') ?? '') !== '') redirect(303, '/contact/thanks');

		if (!name || name.length > 100 || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) || email.length > 254 || !message || message.length > 5000) {
			return fail(400, { error: 'Please check the fields and try again.', name, email, message });
		}

		try {
			// The one line the project replaces: webhook, email provider API or database insert.
			if (!FORM_WEBHOOK_URL) throw new Error('FORM_WEBHOOK_URL is not set');
			const res = await fetch(FORM_WEBHOOK_URL, {
				method: 'POST',
				headers: { 'Content-Type': 'application/json' },
				body: JSON.stringify({ name, email, message }),
				signal: AbortSignal.timeout(8000)
			});
			if (!res.ok) throw new Error(`webhook answered ${res.status}`); // RES-008: no success without delivery
		} catch (cause) {
			console.error('contact delivery failed', cause);
			return fail(502, { error: 'We could not send your message. Please try again later.', name, email, message });
		}
		redirect(303, '/contact/thanks');
	}
} satisfies Actions;

