import type { Handle } from '@sveltejs/kit/hooks';

// SEC-010: the headers kit.csp does not send. The CSP itself comes from `csp` in vite.config.js.
const STATIC_HEADERS: Record<string, string> = {
	'X-Content-Type-Options': 'nosniff',
	'Referrer-Policy': 'strict-origin-when-cross-origin',
	'Permissions-Policy': 'camera=(), microphone=(), geolocation=()'
};

export const securityHeaders: Handle = async ({ event, resolve }) => {
	const response = await resolve(event);
	// Responses such as redirects can have immutable headers; copy before editing.
	const out = new Response(response.body, response);
	for (const [name, value] of Object.entries(STATIC_HEADERS)) out.headers.set(name, value);
	// HSTS only over HTTPS (also behind a TLS-terminating proxy).
	if (event.url.protocol === 'https:' || event.request.headers.get('x-forwarded-proto') === 'https') {
		out.headers.set('Strict-Transport-Security', 'max-age=63072000; includeSubDomains');
	}
	// PRF-008: HTML revalidates. Use `private, no-store` instead for per-user pages.
	if ((out.headers.get('content-type') ?? '').startsWith('text/html') && !out.headers.has('cache-control')) {
		out.headers.set('Cache-Control', 'public, max-age=0, must-revalidate');
	}
	return out;
};

