// Prerendered pages are served by the host, not by SvelteKit, so `handle` never runs for them and kit.csp only
// reaches them as a <meta> tag - which cannot carry frame-ancestors. Run this after the build
// (node scripts/write-headers.mjs build) to write the same policy, plus the other headers, as a `_headers` file
// (Netlify, Cloudflare Pages; convert for nginx/Apache). Pass the folder that is published as the site root.
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(process.argv[2] ?? 'build');
const GLOBAL = [
	'X-Content-Type-Options: nosniff',
	'Referrer-Policy: strict-origin-when-cross-origin',
	'Permissions-Policy: camera=(), microphone=(), geolocation=()',
	'Strict-Transport-Security: max-age=63072000; includeSubDomains'
];

function htmlFiles(dir) {
	return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
		const full = path.join(dir, entry.name);
		return entry.isDirectory() ? htmlFiles(full) : entry.name.endsWith('.html') ? [full] : [];
	});
}

const blocks = [
	['/*', [...GLOBAL, ...(process.env.DEPLOY_ENV === 'production' ? [] : ['X-Robots-Tag: noindex, nofollow'])]],
	['/_app/immutable/*', ['Cache-Control: public, max-age=31536000, immutable']] // PRF-008
];
for (const file of htmlFiles(root)) {
	const meta = fs.readFileSync(file, 'utf8').match(/<meta http-equiv="content-security-policy" content="([^"]*)"/i);
	if (!meta) continue;
	let csp = meta[1].replace(/&amp;/g, '&').replace(/&#39;|&apos;/g, "'").trim().replace(/;$/, '');
	if (!/frame-ancestors/.test(csp)) csp += "; frame-ancestors 'none'";
	const rel = path.relative(root, file).split(path.sep).join('/');
	const url = '/' + rel.replace(/(^|\/)index\.html$/, '$1').replace(/\.html$/, '');
	blocks.push([url, [`Content-Security-Policy: ${csp}`, 'Cache-Control: public, max-age=0, must-revalidate']]);
}
fs.writeFileSync(
	path.join(root, '_headers'),
	blocks.map(([url, lines]) => `${url}\n${lines.map((line) => `  ${line}`).join('\n')}`).join('\n\n') + '\n'
);
console.log(`wrote ${path.join(root, '_headers')} (${blocks.length - 2} pages)`);

