import type { Handle } from '@sveltejs/kit/hooks';
import { DEPLOY_ENV } from '$app/env/private';

// IDX-005: only DEPLOY_ENV=production is production. Everything else is told not to be indexed.
export const noindexUnlessProduction: Handle = async ({ event, resolve }) => {
	const response = await resolve(event);
	if (DEPLOY_ENV === 'production') return response;
	const out = new Response(response.body, response);
	out.headers.set('X-Robots-Tag', 'noindex, nofollow');
	return out;
};

