					'Allow: /',
					// app and API paths only; never /_app/ (SvelteKit's JS and CSS), images or fonts (IDX-004)
					'Disallow: /api/',
					'Disallow: /account/',
					'',
					`Sitemap: ${SITE_URL}/sitemap.xml`
				]
			: ['User-agent: *', 'Disallow: /']; // IDX-005: no Sitemap line outside production
	return new Response(lines.join('\n') + '\n', {
		headers: { 'Content-Type': 'text/plain; charset=utf-8' }
