import type { RequestHandler } from './$types';
import { DEPLOY_ENV, SITE_URL } from '$app/env/private';

export const prerender = false;

// Every static +page.svelte becomes a URL. Leave out app, API and utility pages (IDX-001 needs indexable pages only).
const EXCLUDE = ['/api', '/account', '/gone', '/contact/thanks'];
const files = Object.keys(import.meta.glob('/src/routes/**/+page.svelte'));

const staticPaths = files
	.map((file) => file.replace('/src/routes', '').replace(/\/?\+page\.svelte$/, '').replace(/\/\([^/]+\)/g, ''))
	.map((path) => path || '/')
	.filter((path) => !path.includes('[') && !EXCLUDE.some((p) => path === p || path.startsWith(p + '/')));

// Add database-driven pages here, e.g. products.map((p) => `/products/${p.slug}`).
const dynamicPaths: string[] = [];

const escapeXml = (s: string) =>
	s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');

export const GET: RequestHandler = () => {
	if (DEPLOY_ENV !== 'production') error(404, 'Not found'); // IDX-005: no sitemap outside production
	// Same form as the canonical tags: SvelteKit's default trailingSlash is 'never', so no trailing slash except the root.
	const urls = [...new Set([...staticPaths, ...dynamicPaths])].sort();
	if (urls.length > 50000) error(500, 'Split into a sitemap index (IDX-002)');
	const body = urls.map((path) => `<url><loc>${escapeXml(SITE_URL + path)}</loc></url>`).join('');
	return new Response(
		`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${body}</urlset>`,
		{ headers: { 'Content-Type': 'application/xml; charset=utf-8' } }
	);
};
